/* ============================================
   THE AGENT RING (agentRingProps)
   The AI gradient around whatever an agent is
   working on: a section, a table, a row, a
   card, a field. AiButton's ring recipe (the
   gradient masked to a --border-050 band),
   overlaid on the element's ::after so it never
   moves layout. Colour only: the fill is the
   host's.

   Two hooks let any surface wear it:
   --ds-agent-ring-offset stands the ring clear
   of the element (a borderless section), and
   --ds-agent-ring-radius gives a square surface
   corners. The defaults sit flush on the
   element's own edge and radius.
   ============================================ */

@property --ds-agent-ring-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

/* Zero specificity, so a host's own position always wins: the ring only
   needs a containing block, which absolute and fixed already are. */
:where(.ds-agent-ring) {
  position: relative;
}

.ds-agent-ring:is(
    [data-agent-state='thinking'],
    [data-agent-state='working'],
    [data-agent-state='waiting'],
    [data-agent-state='done'],
    [data-agent-state='error']
  )::after {
  --ds-agent-ring-start: var(--color-ai-gradient-start);
  --ds-agent-ring-mid: var(--color-ai-gradient-mid);
  --ds-agent-ring-end: var(--color-ai-gradient-end);

  content: '';
  position: absolute;
  inset: calc(-1 * var(--ds-agent-ring-offset, 0px));
  z-index: 1;
  border-radius: var(--ds-agent-ring-radius, inherit);
  padding: var(--border-050);
  background: conic-gradient(
    from var(--ds-agent-ring-angle),
    var(--ds-agent-ring-start),
    var(--ds-agent-ring-mid),
    var(--ds-agent-ring-end),
    var(--ds-agent-ring-mid),
    var(--ds-agent-ring-start)
  );
  /* ds-allow(color): mask luminance keying — the #fff paints alpha coverage
     for mask-composite, not a theme colour */
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  animation: ds-agent-ring-in var(--motion-duration-base) var(--motion-ease-entrance) both;
}

/* Thinking and working: the busy spin AiButton's ring takes, one turn per
   spinner rotation. */
.ds-agent-ring:is([data-agent-state='thinking'], [data-agent-state='working'])::after {
  animation:
    ds-agent-ring-in var(--motion-duration-base) var(--motion-ease-entrance) both,
    ds-agent-ring-spin var(--motion-duration-loop-spin) var(--motion-ease-linear) infinite;
}

/* Waiting: the warning family's border colour, breathing on the matrix's
   cycle the way the dots do, so a ring that waits reads like a mark that
   waits. */
.ds-agent-ring[data-agent-state='waiting']::after {
  --ds-agent-ring-start: var(--color-status-warning-border);
  --ds-agent-ring-mid: var(--color-status-warning-border);
  --ds-agent-ring-end: var(--color-status-warning-border);
  animation:
    ds-agent-ring-in var(--motion-duration-base) var(--motion-ease-entrance) both,
    ds-agent-ring-breathe var(--motion-duration-loop-matrix) var(--motion-ease-standard) infinite;
}

/* Done and error: the status family's border colour for a beat, then the
   ring fades off and the element is left as it was. */
.ds-agent-ring[data-agent-state='done']::after {
  --ds-agent-ring-start: var(--color-status-positive-border);
  --ds-agent-ring-mid: var(--color-status-positive-border);
  --ds-agent-ring-end: var(--color-status-positive-border);
}

.ds-agent-ring[data-agent-state='error']::after {
  --ds-agent-ring-start: var(--color-status-error-border);
  --ds-agent-ring-mid: var(--color-status-error-border);
  --ds-agent-ring-end: var(--color-status-error-border);
}

.ds-agent-ring:is([data-agent-state='done'], [data-agent-state='error'])::after {
  /* ds-allow(motion): the 2s beat mirrors MOTION_FEEDBACK_RESET_MS, the hold
     AiButton's done and error take, so the ring and the button settle
     together */
  animation: ds-agent-ring-settle 2000ms var(--motion-ease-standard) forwards;
}

@keyframes ds-agent-ring-in {
  from {
    opacity: 0;
  }
}

@keyframes ds-agent-ring-spin {
  to {
    --ds-agent-ring-angle: 360deg;
  }
}

/* The ring's breath keeps the band legible at its low point: the dots dim
   to a fifth, but a ring that faded that far would read as switching off. */
@keyframes ds-agent-ring-breathe {
  0%,
  100% {
    opacity: 0.45;
  }

  50% {
    opacity: 1;
  }
}

@keyframes ds-agent-ring-settle {
  0%,
  80% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

/* ============================================
   REDUCED MOTION
   The global guard collapses every animation to
   its final frame, which for the matrix is dark.
   Park it at a legible resting state instead and
   let the label carry the meaning on its own.
   ============================================ */

/* ds-allow(motion): parks a looping animation, which the collapsed duration would strobe rather than stop (the dot cycle, the label shimmer and the agent ring's turn). */
@media (prefers-reduced-motion: reduce) {
  .ds-agent-status.ds-agent-status--done .ds-agent-status__dot:nth-child(n),
  .ds-agent-status.ds-agent-status--error .ds-agent-status__dot:nth-child(n),
  .ds-agent-status-mark.ds-agent-status-mark--done .ds-agent-status-mark__dot:nth-child(n),
  .ds-agent-status-mark.ds-agent-status-mark--error .ds-agent-status-mark__dot:nth-child(n),
  .ds-agent-status--animated.ds-agent-status--twinkle .ds-agent-status__dot:nth-child(n),
  .ds-agent-status-mark--animated.ds-agent-status-mark--twinkle .ds-agent-status-mark__dot:nth-child(n) {
    animation: none;
  }

  .ds-agent-status--animated .ds-agent-status__dot,
  .ds-agent-status-mark--animated .ds-agent-status-mark__dot {
    animation: none;
    opacity: 0.55;
    transform: none;
  }

  /* The ring stops turning and breathing and stays; the done and error fade
     still runs, being a change of opacity rather than movement. */
  .ds-agent-ring:is([data-agent-state='thinking'], [data-agent-state='working'])::after,
  .ds-agent-ring[data-agent-state='waiting']::after {
    animation: none;
  }

  .ds-agent-status__label--shimmer {
    background-image: none;
    color: var(--ds-agent-label-color);
    animation: none;
  }
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import type { AgentStatusPattern, AgentStatusState } from './AgentStatusPatterns';
import './AgentStatus.css';

/** The dot grid — 12 cells, row-major. CSS owns which cell lights when. */
const DOT_COUNT = 12;

/** Fallback copy per state, used when no `label` is given. */
const DEFAULT_LABELS: Record<AgentStatusState, string> = {
  idle: 'Idle',
  thinking: 'Thinking',
  working: 'Working',
  waiting: 'Waiting for you',
  done: 'Done',
  error: 'Failed',
};

/** States where the matrix animates and the label may shimmer. */
const ACTIVE_STATES: readonly AgentStatusState[] = ['thinking', 'working', 'waiting'];

/** Props owned by AgentStatus itself — everything else falls through to the root element. */
type AgentStatusOwnProps = {
  /** What the agent is doing. Drives the colour, the default label, and whether the matrix animates. */
  state?: AgentStatusState;
  /** Status text. Falls back to a default for the state. Ignored when `children` are given. */
  label?: string;
  /** Which dot-matrix choreography to run. Defaults to `breathe` while `waiting`, a still pulse that reads as the person's turn (the same as AgentStatusMark), and `orbit` otherwise. */
  pattern?: AgentStatusPattern;
  /**
   * Sweep a highlight across the label while the agent is active. Defaults to
   * on for `thinking`, `working` and `waiting`, off for the resting states.
   */
  shimmer?: boolean;
  /**
   * Indicator and text scale, paired with ChatMessage's sizes: `default`
   * matches default message text, `compact` matches compact message text.
   * `sm` and `md` are legacy aliases for `compact` and `default`.
   */
  size?: 'default' | 'compact' | 'sm' | 'md';
  /**
   * `inline` sits in a line of content; `bar` is a full-width row for the
   * top of a panel; `pill` is a glass pill for a status that floats over
   * the page while a run goes on; once it ends the dots fill solid in the
   * status colour, as in every variant. The pill does not position itself.
   */
  variant?: 'inline' | 'bar' | 'pill';
  /** A trailing control after the status text, such as a link that opens the run. Meant for the `pill` and `bar` variants. */
  action?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
  /** Status text, when it needs markup the `label` string cannot express. */
  children?: React.ReactNode;
};

export interface AgentStatusProps
  extends AgentStatusOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof AgentStatusOwnProps> {}

/**
 * AgentStatus reports what an agent is doing right now: a dot-matrix indicator
 * beside a line of status text.
 *
 * Colour carries meaning rather than decoration — the three working states are
 * monochrome, and only `waiting`, `done` and `error` take a status colour.
 * The whole thing is one polite live region, so a screen reader hears the state
 * change without the caller wiring anything up.
 */
export const AgentStatus = React.forwardRef<HTMLDivElement, AgentStatusProps>(
  (
    {
      state = 'thinking',
      label,
      pattern,
      shimmer,
      size = 'default',
      variant = 'inline',
      action,
      className = '',
      children,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-agent-status';
    const isActive = ACTIVE_STATES.includes(state);
    const isShimmering = shimmer ?? isActive;
    // Legacy aliases: sm/md predate the chat set settling on ChatMessage's names.
    const resolvedSize = size === 'sm' ? 'compact' : size === 'md' ? 'default' : size;

    /* When the label string changes, the old text fades up and out while
       the new one fades up and in — a status that narrates progress should
       glide between steps, not snap. Only string labels transition;
       `children` are consumer-owned markup and render as-is. */
    const resolvedLabel = label ?? DEFAULT_LABELS[state];
    const [outgoing, setOutgoing] = useState<string | null>(null);
    const lastLabel = useRef(resolvedLabel);
    useEffect(() => {
      if (children != null) return;
      if (lastLabel.current !== resolvedLabel) {
        setOutgoing(lastLabel.current);
        lastLabel.current = resolvedLabel;
      }
    }, [resolvedLabel, children]);
    const isSwapping = outgoing !== null;

    const classes = [
      baseClass,
      `${baseClass}--${state}`,
      `${baseClass}--${pattern ?? (state === 'waiting' ? 'breathe' : 'orbit')}`,
      `${baseClass}--${resolvedSize}`,
      `${baseClass}--${variant}`,
      isActive ? `${baseClass}--animated` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <div {...rest} ref={ref} className={classes} role="status">
        <span className={`${baseClass}__matrix`} aria-hidden="true">
          {Array.from({ length: DOT_COUNT }, (_, i) => (
            <span key={i} className={`${baseClass}__dot`} />
          ))}
        </span>
        <span
          className={`${baseClass}__label${
            isShimmering ? ` ${baseClass}__label--shimmer` : ''
          }${isSwapping ? ` ${baseClass}__label--swapping` : ''}`}
        >
          {children ?? (
            <>
              {isSwapping && (
                <span
                  className={`${baseClass}__label-text ${baseClass}__label-text--out`}
                  aria-hidden="true"
                >
                  {outgoing}
                </span>
              )}
              <span
                key={resolvedLabel}
                className={`${baseClass}__label-text${
                  isSwapping ? ` ${baseClass}__label-text--in` : ''
                }`}
                onAnimationEnd={(e) => {
                  if (e.target === e.currentTarget) setOutgoing(null);
                }}
              >
                {resolvedLabel}
              </span>
            </>
          )}
        </span>
        {action != null && <span className={`${baseClass}__action`}>{action}</span>}
      </div>
    );
  },
);

AgentStatus.displayName = 'AgentStatus';

/** The mark's square grid: 4x4, row-major. CSS owns which cell lights when. */
const MARK_DOT_COUNT = 16;

/** Props owned by AgentStatusMark itself — everything else falls through to the <span>. */
type AgentStatusMarkOwnProps = {
  /** What the agent is doing. Drives the colour and whether the dots animate, as on AgentStatus. */
  state?: AgentStatusState;
  /** Which choreography to run: every AgentStatus pattern, redrawn for the square grid. Defaults to `breathe` while `waiting`, a still pulse that reads as the person's turn, and `orbit` otherwise. */
  pattern?: AgentStatusPattern;
  /** Additional CSS classes */
  className?: string;
};

export interface AgentStatusMarkProps
  extends AgentStatusMarkOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof AgentStatusMarkOwnProps | 'children'> {}

/**
 * AgentStatus's dots at icon size, for an icon slot: a square 4x4 grid sized
 * by `--icon-size`, drawn inside a Material Symbol's live area, so it swaps
 * with a glyph without moving or outgrowing it. Every AgentStatus pattern
 * runs on it, redrawn for the square, in AgentStatus's cycle and colours;
 * orbit is the default, and breathe while waiting. AiButton's status is
 * the first host.
 * Hidden from assistive technology; the host announces the state.
 */
export const AgentStatusMark = React.forwardRef<HTMLSpanElement, AgentStatusMarkProps>(
  ({ state = 'working', pattern, className = '', ...rest }, ref) => {
    const baseClass = 'ds-agent-status-mark';
    const classes = [
      baseClass,
      `${baseClass}--${state}`,
      `${baseClass}--${pattern ?? (state === 'waiting' ? 'breathe' : 'orbit')}`,
      ACTIVE_STATES.includes(state) ? `${baseClass}--animated` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');
    return (
      <span aria-hidden="true" {...rest} ref={ref} className={classes}>
        {Array.from({ length: MARK_DOT_COUNT }, (_, i) => (
          <span key={i} className={`${baseClass}__dot`} />
        ))}
      </span>
    );
  },
);

AgentStatusMark.displayName = 'AgentStatusMark';
